// spec: specs/notifications.md
// seed: tests/seed.client.spec.ts
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/client.json') });

test.describe('התראות — לחיצה על התראה', () => {
  test('לקוח: התראת "ארנק" רק מסומנת כנקראה — המסך לא משתנה @mobile @data (#ccd9d865)', async ({ page }) => {
    // 1. /notifications → פילטר "ארנק"
    await page.goto('/notifications');
    await page.getByTestId('chip-wallet').click();

    const card = page
      .getByTestId(/^notification-[0-9a-f-]{36}$/)
      .filter({ hasText: 'פעולה נחסמה בגלל מגבלה' })
      .first();
    await expect(card).toBeVisible();
    await expect(card).toContainText('הפעולה נחסמה כי היא חורגת מהמגבלה שהוגדרה.');
    const cardTestId = (await card.getAttribute('data-testid'))!;

    // 2. ללחוץ על הכרטיס הראשון "פעולה נחסמה בגלל מגבלה"
    await card.click();
    await expect(page.getByTestId(cardTestId)).toHaveCSS('background-color', 'rgb(255, 255, 255)');
    await expect(page).toHaveURL(/\/notifications$/);
  });
});
